// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address to, uint256 v) public {
        address[] memory tos = new address[](1);
        tos[0] = to;

        Recorder rec = new Recorder();
        vm.assume(from != address(rec));

        c.transfer(from, address(rec), tos, v);

        assertTrue(rec.count() == tos.length && rec.successCount() == tos.length);
    }
}

contract Recorder {
    uint256 public count;
    uint256 public successCount;
    bytes public lastData;

    function transferFrom(address, address, uint256) external returns (bool) {
        count++;
        successCount++;
        lastData = msg.data;
        return true;
    }

    fallback() external payable {
        revert();
    }
}
